<style>
.fulfillment-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(340px,.8fr);gap:1rem}.fulfillment-stack{display:grid;gap:1rem}.fulfillment-card{border:1px solid var(--border);border-radius:18px;background:var(--surface);padding:1rem}.fulfillment-card h3{margin:.2rem 0 .35rem}.fulfillment-card p{margin:.2rem 0;color:var(--muted)}.fulfillment-kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.65rem;margin-top:.8rem}.fulfillment-kpis div{padding:.7rem;border:1px solid var(--border);border-radius:14px;background:var(--surface-soft)}.fulfillment-kpis span{display:block;font-size:.76rem;color:var(--muted)}.fulfillment-kpis strong{font-size:1.05rem}.match-good{border-left:4px solid #15803d}.match-warn{border-left:4px solid #b45309}.match-block{border-left:4px solid #b91c1c}.timeline{display:grid;gap:.65rem}.timeline article{display:grid;grid-template-columns:130px 1fr auto;gap:.8rem;padding:.7rem 0;border-bottom:1px solid var(--border)}.timeline article:last-child{border-bottom:0}.inline-actions{display:flex;gap:.5rem;flex-wrap:wrap}.compact-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.7rem}.compact-form .span-2{grid-column:span 2}@media(max-width:980px){.fulfillment-grid{grid-template-columns:1fr}.fulfillment-kpis{grid-template-columns:1fr}.compact-form{grid-template-columns:1fr}.compact-form .span-2{grid-column:auto}.timeline article{grid-template-columns:1fr}}
</style>
